-- What a marketing ad may say about each Tomverse feature (owner request
-- 2026-11-12), edited in Admin and read by the box's Higgsfield image job.
-- Seeded with tools/marketing-video/features.json as it stood on 2026-11-12;
-- that file stays as the job's fallback.
CREATE TABLE "MarketingFeatureFact" (
    "id" TEXT NOT NULL,
    "position" INTEGER NOT NULL,
    "what" TEXT NOT NULL,
    "models" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    "realExample" JSONB,
    "copy" TEXT,
    "disclosure" JSONB,
    "source" TEXT NOT NULL,
    "hold" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "MarketingFeatureFact_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "MarketingFeatureFact_position_idx" ON "MarketingFeatureFact"("position");

INSERT INTO "MarketingFeatureFact" ("id", "position", "what", "models", "realExample", "copy", "disclosure", "source", "hold", "updatedAt") VALUES
    ('chat', 0, 'Chat with leading models in one workspace: continue a conversation with one model, and pick the model per question.', ARRAY['GPT 6 Luna', 'Claude Sonnet 5.5', 'Claude Haiku 5.5', 'Gemini Flash']::TEXT[], NULL, NULL, NULL, 'claim.chat-and-review; model chips in the app', NULL, CURRENT_TIMESTAMP),
    ('smart-adaptive', 1, 'Smart Adaptive: Tomverse picks a model for each message, weighing the question, the capabilities it needs, cost and quality, and the reply shows which model answered. You can still pick a model yourself.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'FAQ ''Can I choose a model myself with Smart Adaptive?''; lib/autoRoutingCopy.ts', NULL, CURRENT_TIMESTAMP),
    ('review', 2, 'Ask one question to three models at once and read the answers side by side. Easy mode: pick the companies and Tomverse picks a model for each question; Professional mode: pick the exact models.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'claim.review-three-models; claim.review-modes', NULL, CURRENT_TIMESTAMP),
    ('analysis', 3, 'Tomverse answer analysis: where the answers agree, where they differ, what is missing, what needs checking, and contradictions, each point with the answers'' own quotes. It does not say which answer is right.', ARRAY[]::TEXT[], '{"question":"Planning a 2-day trip near Sydney with my elderly parents. Suggest an itinerary with very little walking.","models":["GPT 6 Luna","Claude Haiku 5.5","Gemini Flash"],"counts":{"consensus":7,"importantDifferences":6,"missingPoints":7,"verificationNeeded":6,"contradictions":1},"contradiction":"Gemini Flash: \"Skip the Scenic Railway (which has steep steps)\". Claude Haiku 5.5: \"The Scenic Railway runs down a steep incline in a seated, enclosed carriage\"."}'::jsonb, NULL, NULL, 'real analysis recorded 2026-11-01 (marketing-reels/en-compare-short/rec/lang-en/analysis.txt)', NULL, CURRENT_TIMESTAMP),
    ('deep-research', 4, 'Deep Research: for a question where many sources matter, turn on Deep Research and get a report written from the sources it searched; a report can take several minutes. In Review''s Professional mode you decide whether to use it.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'claim.review-modes; Deep Research status and setup copy in locales/en.ts', NULL, CURRENT_TIMESTAMP),
    ('images', 5, 'Sign in, describe an image once, generate it with one or more image models and compare the results side by side; keep the one you like.', ARRAY['GPT Image 2', 'Nano Banana 2', 'Grok Imagine']::TEXT[], NULL, NULL, NULL, 'claim.chat-image-generation (gate feature.imageGeneration, on in production per the owner 2026-11-12); image model chips in the app', NULL, CURRENT_TIMESTAMP),
    ('files', 6, 'Ask about your files: attach a PDF, a document or a spreadsheet, or pick one from Google Drive after signing in, and ask questions about it.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'claim.chat-file-questions', NULL, CURRENT_TIMESTAMP),
    ('file-conversion', 7, 'Attach files in Chat and ask in plain words to convert them: photos and PDF pages into one PDF (merge, pick pages, reorder, rotate), one PDF split into several, PDF pages into images, images to another format or size, and an Excel or CSV sheet to Excel, CSV or a PDF table. The converted file comes back in the chat to download.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'convert_files tool (branch claude/office-file-conversions, docs/policy/generated-artifacts.md §14), deployed 2026-11-12 per the owner; on by default (CHAT_FILE_CONVERSION=off removes it)', NULL, CURRENT_TIMESTAMP),
    ('web-search', 8, 'Turn on web search so answers come with their sources.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'web search chip in the composer', NULL, CURRENT_TIMESTAMP),
    ('assistants', 9, 'Sign in and build your own AI assistant: give it a name and instructions, add your files, pick a model, and start conversations with it again and again. It stays private to your account.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'claim.chat-assistants (gate feature.assistantProfiles, on in production per the owner 2026-11-12)', NULL, CURRENT_TIMESTAMP),
    ('projects', 10, 'Projects: sign in, create a project and move your conversations into it, so a move, a trip or a job keeps its chats together. A project is a folder; it does not share files or memory between its chats.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'help centre ''Use projects'' (chatWorkspaceGuideContent.ts)', NULL, CURRENT_TIMESTAMP),
    ('save-and-share', 11, 'Sign in to save your conversations, lock one with a password, and share one as a read-only link.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'claim.save-and-share; help centre ''Locking and sharing''', NULL, CURRENT_TIMESTAMP),
    ('import-continue', 12, 'Sign in and import your past conversations from another AI service (ChatGPT, Claude or Gemini) with its official data export, then continue a conversation in Tomverse: the model you select refers to the past context when it answers.', ARRAY[]::TEXT[], NULL, 'Write within these approved claims: you can import past conversations from another AI service; the model you select refers to that past context; Tomverse can draft a custom AI profile from imported conversations. Never say or show that memories, a personality or a style are copied or recreated, that nothing is lost or everything moves over, that answers are the same as before or ''just like ChatGPT/Claude'', that OpenAI, Anthropic or Google endorse it, or that hidden prompts are recovered (docs/policy/external-conversation-import-and-memory.md §17).', '{"en":"Answers draw on your past chats and the memories you approve, and come from the model you choose, so they may differ from the original service.","ko":"과거 대화와 승인한 기억을 참고하며, 답변은 고른 모델이 만들기 때문에 원래 서비스와 다를 수 있습니다.","zh-Hant":"回答會參考您過去的對話與您核准的記憶，並由您選擇的模型產生，因此可能與原本的服務不同。","zh-Hans":"回答会参考您过去的对话与您批准的记忆，并由您选择的模型生成，因此可能与原来的服务不同。"}'::jsonb, 'claim.chat-import-and-continue; lib/marketingMemoryClaims.ts ALLOWED_MEMORY_CLAIMS and MEMORY_MARKETING_SHORT_DISCLOSURE (§17.1, owner 2026-11-12)', NULL, CURRENT_TIMESTAMP),
    ('memory', 13, 'Account memory: Tomverse keeps memories that you review and approve, uses them in new conversations, and refers to the answer style you prefer from past conversations.', ARRAY[]::TEXT[], NULL, 'Write within these approved claims: memories you review and approve are used in new conversations; the answer style you prefer is referred to. Never say or show that memories, a personality or a style are copied or recreated, that nothing is lost or everything moves over, that answers are the same as before or ''just like ChatGPT/Claude'', that OpenAI, Anthropic or Google endorse it, or that hidden prompts are recovered (docs/policy/external-conversation-import-and-memory.md §17).', '{"en":"Answers draw on your past chats and the memories you approve, and come from the model you choose, so they may differ from the original service.","ko":"과거 대화와 승인한 기억을 참고하며, 답변은 고른 모델이 만들기 때문에 원래 서비스와 다를 수 있습니다.","zh-Hant":"回答會參考您過去的對話與您核准的記憶，並由您選擇的模型產生，因此可能與原本的服務不同。","zh-Hans":"回答会参考您过去的对话与您批准的记忆，并由您选择的模型生成，因此可能与原来的服务不同。"}'::jsonb, 'lib/marketingMemoryClaims.ts ALLOWED_MEMORY_CLAIMS and MEMORY_MARKETING_SHORT_DISCLOSURE (§17.1, owner 2026-11-12); memory live since 2026-10-23', NULL, CURRENT_TIMESTAMP),
    ('plugins', 14, 'Plugins: connect your work tools to Chat and manage access and actions in one place; an action that changes something waits for your approval.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'lib/mcpConnectorCopy.ts; /plugins', 'Not live: production has no connectable server. Needs MCP_CONNECTOR_PREVIEW_ENABLED=true plus each provider''s OAuth credentials (MCP_CONNECTOR_PROVIDERS, docs/ops/mcp-connector-preview.md); then name the connectable tools here and remove this hold.', CURRENT_TIMESTAMP),
    ('voice-input', 15, 'Speak into the microphone in the message box and your words become text.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'locales/en.ts voice input copy', 'Not live: set VOICE_PROVIDER_SECONDS_PER_DAY and _PER_MONTH on the web service first (without them /api/ready fails), then the feature.voiceInputEnabled row to "true" (docs/policy/voice-input.md; no Admin toggle).', CURRENT_TIMESTAMP),
    ('prompt-refiner', 16, 'Question-refinement suggestions: when offered, Tomverse suggests a clearer version of your question, and you choose whether to apply it.', ARRAY[]::TEXT[], NULL, NULL, NULL, 'FAQ ''Are question-refinement suggestions applied automatically?''', 'Not live: the owner activates it for the exact deployment in Admin › /admin/prompt-refiner-shadow (re-auth, audited), as docs/ui-contracts/prompt-refiner-suggestion.md requires.', CURRENT_TIMESTAMP),
    ('photo-edit', 17, 'Sign in, attach a photo in Chat and ask in plain words to change it (remove an object, change the background, adjust a detail); an image model edits the photo and the result comes back in the chat. Editing uses credits, shown before it runs.', ARRAY['GPT Image 2', 'Nano Banana 2', 'Grok Imagine']::TEXT[], NULL, NULL, NULL, '#3118, #3134 (chat photo edit); IMAGE_EDIT_ENABLED=true on the production web service 2026-11-12 with the owner''s price approval (docs/policy/image-generation.md)', NULL, CURRENT_TIMESTAMP);
